#!/usr/bin/env bash
set -euo pipefail
ROOT=$(cd "$(dirname "$0")/.."&&pwd);OUT=$ROOT/work/results/l5_recip;mkdir -p "$OUT";R=$ROOT/scripts/run_memory_capped.sh;V=$ROOT/work/toolchain/conda/bin/verilator;PY=$ROOT/work/toolchain/cnn_py312/bin/python
"$ROOT/scripts/generate_fp32_primitives.sh";taskset -c 8-23 "$PY" "$ROOT/scripts/generate_recip_pwl_coeffs.py" --svh "$ROOT/rtl/sfu/fp32_recip_coeffs.svh" --json "$ROOT/config/fp32_recip_coeffs.json";taskset -c 8-23 "$PY" "$ROOT/scripts/generate_recip_vectors.py" --output "$OUT/vectors.memh" --manifest "$OUT/vectors.json"
MIN_AVAILABLE_KIB=10485760 MEMORY_HIGH=24G MEMORY_MAX=30G "$R" "$V" --lint-only --timing -Wall -Wno-DECLFILENAME -Wno-TIMESCALEMOD -Wno-UNUSEDSIGNAL --top-module tb_fp32_reciprocal_nr "$ROOT/work/generated/l5_fp32_primitives/HeteroFP32Primitives.sv" "$ROOT/rtl/sfu/fp32_reciprocal_nr.sv" "$ROOT/tb/tb_fp32_reciprocal_nr.sv" >"$OUT/lint.log" 2>&1
MIN_AVAILABLE_KIB=10485760 MEMORY_HIGH=24G MEMORY_MAX=30G "$R" "$V" --binary --threads 4 --timing -Wall -Wno-DECLFILENAME -Wno-TIMESCALEMOD -Wno-UNUSEDSIGNAL -Wno-UNOPTTHREADS -j 4 -MAKEFLAGS "AR=/usr/bin/ar CXX=/usr/bin/g++" --top-module tb_fp32_reciprocal_nr --Mdir "$OUT/obj" -o tb "$ROOT/work/generated/l5_fp32_primitives/HeteroFP32Primitives.sv" "$ROOT/rtl/sfu/fp32_reciprocal_nr.sv" "$ROOT/tb/tb_fp32_reciprocal_nr.sv" >"$OUT/build.log" 2>&1
MIN_AVAILABLE_KIB=10485760 MEMORY_HIGH=24G MEMORY_MAX=30G "$R" "$OUT/obj/tb"|tee "$OUT/tb.log";grep -q 'FP32_RECIPROCAL_NR_PASS vectors=10000' "$OUT/tb.log";echo L5_RECIPROCAL_GATE_PASS
